#include <stdio.h>
#include <queue>
#include <utility>

using namespace std;

int main()
{
    int n;
    int degree[15];
    int ans = 0;

    scanf("%d", &n);

    for (int i = 0; i < n; i++)
        scanf("%d", &degree[i]);

    queue<pair<int, int>> q;
    q.push(make_pair(0, 0));

    while (!q.empty())
    {
        int index = q.front().first;
        int sum = q.front().second;
        q.pop();

        if (index == n)
        {
            if (sum % 360 == 0)
            {
                ans = 1;
                break;
            }
            continue;
        }

        q.push(make_pair(index + 1, sum + degree[index]));
        q.push(make_pair(index + 1, sum - degree[index]));
    }

    printf(ans ? "YES\n" : "NO\n");
    return 0;
}

